<template>
  <section class="design-view">
    <header class="design-header">
      <div><span class="eyebrow">创作控制台</span><h2>生产设计与连续性</h2><p>把创作判断变成 Codex 可读、可追溯、可验收的状态与规则。</p></div>
      <nav><button v-for="entry in tabs" :key="entry.id" :data-testid="`design-tab-${entry.id}`" :class="{active:tab===entry.id}" @click="tab=entry.id"><component :is="entry.icon" :size="14" />{{entry.label}}</button></nav>
    </header>

    <div v-if="loading" class="empty"><LoaderCircle class="spinning" :size="26" />载入生产设计…</div>
    <template v-else-if="tab==='workflow' && workflow">
      <div class="stage-strip">
        <button v-for="(stage,index) in workflow.stages" :key="stage.id" :class="[stage.status,{active:selectedStageId===stage.id,'evidence-ready':stageAudit(stage.id)?.ready,'evidence-bad':stageAudit(stage.id)&&!stageAudit(stage.id)?.ready}]" @click="selectStage(stage.id)"><span>{{String(index+1).padStart(2,'0')}}</span><b>{{stage.name}}</b><small>{{stageLabel(stage.status)}} · {{stageAudit(stage.id)?.ready?'证据就绪':'证据缺口'}}</small></button>
      </div>
      <div class="workflow-body">
        <section class="stage-summary">
          <div class="summary-head"><div><span>实时证据审计</span><b>{{workflow.evidenceAudit?.readyStageCount??0}} / {{workflow.stages.length}}</b></div><button :disabled="saving" @click="reloadWorkflow"><LoaderCircle :class="{spinning:saving}" :size="14" />重新核验</button></div>
          <p>状态不能代替证据。完成阶段会记录验证指纹，领取任务和生成前仍会检查真实文件、哈希、引用、视觉验收与发布回执。</p>
          <div v-if="selectedStageAudit" :class="['audit-result',{ready:selectedStageAudit.ready,bad:!selectedStageAudit.ready}]">
            <span>{{selectedStageAudit.ready?'本阶段证据就绪':'本阶段尚不可完成'}}</span>
            <small v-if="selectedStageAudit.legacyUnverified">旧侧车 completed 尚未建立验证指纹；重新保存完成状态后才能纳入强制漂移检查。</small>
            <ul v-if="selectedStageAudit.issues.length"><li v-for="issue in selectedStageAudit.issues" :key="issue">{{issue}}</li></ul>
            <dl><div v-for="(value,key) in selectedAuditMetrics" :key="key"><dt>{{metricLabel(key)}}</dt><dd>{{value}}</dd></div></dl>
          </div>
          <small class="audit-time" v-if="workflow.evidenceAudit">核验时间 {{formatAuditTime(workflow.evidenceAudit.checkedAt)}} · r{{workflow.evidenceAudit.workflowRevision}}</small>
        </section>
        <section v-if="stageDraft" class="editor-panel">
          <span class="eyebrow">{{stageDraft.id}}</span><h3>{{stageDraft.name}}</h3>
          <label><span>状态</span><select v-model="stageDraft.status"><option value="not_started">未开始</option><option value="in_progress">进行中</option><option value="review">待审核</option><option value="blocked">阻塞</option><option value="completed">已完成</option></select></label>
          <label><span>说明 / 阻塞原因</span><textarea v-model="stageDraft.note" rows="5"></textarea></label>
          <label><span>真实证据路径（每行一个）</span><textarea v-model="stageDraft.evidenceText" rows="6" placeholder="/绝对路径/方案.md"></textarea></label>
          <label><span>关联生产节点 ID（每行一个）</span><textarea v-model="stageDraft.itemText" rows="5"></textarea></label>
          <div class="contract-grid"><label><span>输入要求（每行一条）</span><textarea v-model="stageDraft.inputText" rows="5"></textarea></label><label><span>输出要求</span><textarea v-model="stageDraft.outputText" rows="5"></textarea></label></div>
          <div class="contract-grid"><label><span>验收条件</span><textarea v-model="stageDraft.acceptanceText" rows="6"></textarea></label><label><span>失败 / 返工路径</span><textarea v-model="stageDraft.failureText" rows="6"></textarea></label></div>
          <label><span>Codex 下一动作（每行一个工具或动作）</span><textarea v-model="stageDraft.actionsText" rows="5"></textarea></label>
          <button class="primary-button" data-testid="save-production-stage" :disabled="saving" @click="saveStage"><Save :size="14" />保存阶段</button>
        </section>
      </div>
    </template>

    <template v-else-if="tab==='bibles'">
      <div class="bible-layout">
        <aside class="bible-list"><header><span>Bible</span><button @click="newBible"><Plus :size="14" /></button></header><button v-for="bible in bibles" :key="bible.id" :class="{active:bibleDraft.id===bible.id}" @click="editBible(bible)"><span>{{bible.kind}}</span><b>{{bible.name}}</b><small>r{{bible.revision}} · {{bible.rules.length}} 条规则</small></button><p v-if="!bibles.length">尚未建立导演或视觉 Bible</p></aside>
        <section class="bible-editor">
          <div class="panel-title"><div><span class="eyebrow">创作规则</span><h3>{{bibleDraft.id?'修订 Bible':'新建 Bible'}}</h3></div><button v-if="bibleDraft.id" class="ghost-button" @click="impactBible"><GitBranch :size="14" />影响分析</button></div>
          <div class="form-grid"><label><span>类型</span><select v-model="bibleDraft.kind"><option value="director">导演</option><option value="visual">视觉</option><option value="character">角色</option><option value="world">世界观</option></select></label><label><span>名称</span><input v-model="bibleDraft.name" /></label></div>
          <label><span>总述</span><textarea v-model="bibleDraft.summary" rows="5"></textarea></label>
          <div class="form-grid"><label><span>必须遵守（每行一条）</span><textarea v-model="bibleDraft.rulesText" rows="9"></textarea></label><label><span>禁止项（每行一条）</span><textarea v-model="bibleDraft.forbiddenText" rows="9"></textarea></label></div>
          <label><span>参考文件绝对路径（每行一个）</span><textarea v-model="bibleDraft.referencesText" rows="4"></textarea></label>
          <button class="primary-button" data-testid="save-creative-bible" :disabled="saving||!bibleDraft.name.trim()" @click="saveBible"><Save :size="14" />保存 Bible</button>
          <pre v-if="impact">{{JSON.stringify(impact,null,2)}}</pre>
        </section>
      </div>
    </template>

    <template v-else-if="tab==='storyboard'">
      <div class="storyboard-toolbar"><select v-model="storyboardItemId" :disabled="saving" @change="loadStoryboard"><option v-for="item in units" :key="item.id" :value="item.id">EP{{String(item.episode).padStart(2,'0')}} · 15s {{String(item.unit).padStart(3,'0')}} · {{item.title}}</option></select><button data-testid="build-fusion-storyboard-grid" :disabled="saving||!storyboard.valid" @click="buildStoryboardGrid"><Layers3 :size="14" />构建 2–6 格</button><button data-testid="migrate-fusion-storyboard-evidence" :disabled="saving||!storyboardItemId" @click="migrateStoryboardEvidence"><ShieldCheck :size="14" />迁移槽位证据</button><button data-testid="migrate-fusion-storyboard-sheets" :disabled="!canMigrateSheet" :title="migrationPreview?.blockers.join('；')" @click="migrateStoryboardSheets"><ShieldCheck :size="14" />登记旧板为历史</button><button v-if="gridContract" data-testid="render-fusion-storyboard-sheet" :disabled="!canRenderSheet" :title="sheetState?.readiness.blockers.join('；')" @click="renderStoryboardSheet"><Save :size="14" />本地中文成板</button><button v-if="sheetResult" @click="showStoryboardSheet">定位成板</button><span :class="{bad:!storyboard.valid}">{{storyboard.rows.length}} 段 · {{storyboard.totalDurationSeconds.toFixed(2)}}s · {{selectedCanvasUnit?.fusionStoryboard ? `${selectedCanvasUnit.fusionStoryboard.completedPanelCount}/${selectedCanvasUnit.fusionStoryboard.panelCount} 格` : storyboard.valid?'门禁通过':storyboard.issues.join('；')}}</span><button class="primary-button" @click="newRow"><Plus :size="14" />新增分镜</button></div>
      <section class="fusion-sheet-state" data-testid="fusion-sheet-state">
        <header>
          <div><span>权威成板状态</span><b data-testid="fusion-sheet-current-count">current {{sheetState?.currentSheetId?1:0}}/1</b></div>
          <div class="fusion-sheet-fingerprint"><span>当前输入指纹</span><code data-testid="fusion-sheet-fingerprint">{{expectedSheetFingerprint||'未签发'}}</code></div>
          <small v-if="sheetStateLoading">正在核验真实文件…</small><small v-else>store r{{sheetState?.storeRevision??'—'}} · {{sheetState?.currentSheetId??'无 current'}}</small>
        </header>
        <div class="fusion-sheet-state-body">
          <div class="fusion-sheet-blockers" data-testid="fusion-sheet-blockers">
            <b>成板门禁</b>
            <span v-if="sheetStateError">{{sheetStateError}}</span>
            <template v-else-if="sheetState?.readiness.blockers.length"><span v-for="blocker in sheetState.readiness.blockers" :key="blocker">{{blocker}}</span></template>
            <span v-else-if="sheetState?.readiness.canRender" class="ready">输入证据与合同一致，可本地成板</span>
            <span v-else>当前状态未签发成板许可</span>
            <span v-for="blocker in migrationPreview?.blockers??[]" :key="`migration-${blocker}`">旧板登记：{{blocker}}</span>
          </div>
          <div class="fusion-sheet-history" data-testid="fusion-sheet-history">
            <article v-for="version in sheetHistory" :key="version.sheetId">
              <div><b>{{version.status}}</b><code>{{version.sheetId}}</code><small v-if="version.inputFingerprint">{{version.inputFingerprint}}</small></div>
              <p>{{version.reasons.join('；')||'无额外原因'}}</p>
              <button v-for="artifact in version.artifacts" :key="`${version.sheetId}-${artifact.role}-${artifact.path}`" :title="artifact.path" @click="showSheetArtifact(artifact.path)"><span>{{artifact.role}}{{artifact.pageIndex?` p${artifact.pageIndex}`:''}}</span><code>{{artifact.path}}</code></button>
            </article>
            <p v-if="!sheetHistory.length">尚无历史成板版本</p>
          </div>
        </div>
      </section>
      <section v-if="gridContract" class="storyboard-grid-preview" data-testid="fusion-storyboard-grid-preview">
        <header><div><span>15 秒中文宫格合同</span><b>{{gridContract.selection.panelCount}} 格 · {{gridContract.selection.reason}}</b></div><small>{{gridContract.selection.algorithmVersion}} · {{gridContract.displayTiming.policyVersion}} · {{gridContract.selection.detectedBeatCount}} 节拍 · {{gridContract.contractId}} · storyboard r{{gridContract.sourceStoryboardRevision}} · 逐格纯画面 / 本地中文</small></header>
        <div class="grid-panel-strip">
          <article v-for="panel in gridContract.panels" :key="panel.id" :data-testid="`fusion-grid-panel-${panel.index}`">
            <div class="grid-frame"><span>{{String(panel.index).padStart(2,'0')}}</span><b>{{panel.frameRole==='start'?'首帧':panel.frameRole==='end'?'尾帧':'中间帧'}}</b><small>{{panel.startSeconds.toFixed(1)}}–{{panel.endSeconds.toFixed(1)}}s · {{panelState(panel.index)}}</small><button :data-testid="`enqueue-fusion-grid-panel-${panel.index}`" :disabled="!canEnqueueStoryboardPanel(panel.index)" @click="enqueueStoryboardPanel(panel.index)">加入逐格队列</button><em>{{panel.assetIds.join(' · ')||'无资产'}}</em></div>
            <dl><div><dt>画面 / 动作</dt><dd>{{panel.imageContentAction}}</dd></div><div><dt>景别 / 构图</dt><dd>{{panel.shotComposition}}</dd></div><div><dt>拍摄方式</dt><dd>{{panel.shootingMethod}}</dd></div><div><dt>连续性 / 声音</dt><dd>{{panel.continuitySound}}</dd></div><div><dt>台词 / 字幕</dt><dd>{{panel.dialogueSubtitle}}</dd></div></dl>
          </article>
        </div>
        <footer><b>节奏链</b><span>{{gridContract.footer.summary}}</span><small v-if="sheetResult">成板：{{sheetResult.png.path}}</small></footer>
      </section>
      <div :class="['storyboard-layout',{'with-grid':gridContract}]">
        <section class="storyboard-table"><header><span>镜号</span><span>时长</span><span>景别 / 运镜</span><span>动作</span><span>状态</span></header><button v-for="row in storyboard.rows" :key="row.id" :class="{active:rowDraft.id===row.id}" @click="editRow(row)"><b>{{row.order}}</b><span>{{row.durationSeconds.toFixed(2)}}s</span><span>{{row.shotSize}} · {{row.cameraMovement}}</span><span>{{row.action}}</span><em>{{row.status}}</em></button><p v-if="!storyboard.rows.length">当前 15 秒单元还没有正式分镜</p></section>
        <section class="row-editor">
          <span class="eyebrow">正式分镜行</span><h3>{{rowDraft.id?'编辑镜头':'新镜头'}}</h3>
          <div class="form-grid thirds"><label><span>顺序</span><input v-model.number="rowDraft.order" type="number" min="1" /></label><label><span>时长</span><input v-model.number="rowDraft.durationSeconds" type="number" min="0.1" max="15" step="0.1" /></label><label><span>状态</span><select v-model="rowDraft.status"><option value="draft">草稿</option><option value="confirmed">已确认</option><option value="deprecated">弃用</option></select></label></div>
          <label><span>绑定原镜头</span><select v-model="rowDraft.shotItemId"><option value="">仅绑定 15 秒单元</option><option v-for="shot in unitShots" :key="shot.id" :value="shot.id">{{shot.title}} · {{shot.id}}</option></select></label>
          <details open><summary>导演设计</summary>
            <div class="form-grid thirds"><label><span>景别</span><input v-model="rowDraft.shotSize" placeholder="中景 / 特写" /></label><label><span>机位</span><input v-model="rowDraft.cameraAngle" placeholder="平视 / 过肩" /></label><label><span>焦段</span><input v-model="rowDraft.lens" placeholder="35mm" /></label></div>
            <div class="form-grid"><label><span>运镜</span><input v-model="rowDraft.cameraMovement" placeholder="固定 / 推 / 跟" /></label><label><span>构图</span><input v-model="rowDraft.composition" placeholder="三分构图 / 前后景" /></label></div>
            <label><span>人物调度与站位</span><textarea v-model="rowDraft.staging" rows="3"></textarea></label><label><span>动作与画面</span><textarea v-model="rowDraft.action" rows="4"></textarea></label>
            <div class="form-grid"><label><span>表情</span><input v-model="rowDraft.expression" /></label><label><span>情绪</span><input v-model="rowDraft.emotion" /></label></div>
            <div class="form-grid thirds"><label><span>视线</span><input v-model="rowDraft.eyeline" /></label><label><span>屏幕方向</span><input v-model="rowDraft.screenDirection" /></label><label><span>轴线侧</span><input v-model="rowDraft.axisSide" /></label></div>
            <label><span>导演意图</span><textarea v-model="rowDraft.directorIntent" rows="3"></textarea></label><label><span>情绪意图</span><textarea v-model="rowDraft.emotionalIntent" rows="3"></textarea></label>
          </details>
          <details><summary>对白、旁白与声音</summary>
            <label><span>对白 / 字幕</span><textarea v-model="rowDraft.dialogue" rows="3"></textarea></label><label><span>旁白</span><textarea v-model="rowDraft.narration" rows="3"></textarea></label><label><span>环境音</span><textarea v-model="rowDraft.ambience" rows="3"></textarea></label><label><span>音效（每行一条）</span><textarea v-model="rowDraft.soundEffectsText" rows="3"></textarea></label>
          </details>
          <details open><summary>连续性与参考资产</summary>
            <label><span>前镜连续性</span><textarea v-model="rowDraft.continuityBefore" rows="3"></textarea></label><label><span>后镜连续性</span><textarea v-model="rowDraft.continuityAfter" rows="3"></textarea></label><label><span>连续性备注（每行一条）</span><textarea v-model="rowDraft.continuityNotesText" rows="3"></textarea></label>
            <label><span>角色 / 场景 / 道具参考名（每行一个）</span><textarea v-model="rowDraft.referenceNamesText" rows="3"></textarea></label><label><span>参考文件绝对路径（每行一个）</span><textarea v-model="rowDraft.referencePathsText" rows="4"></textarea></label><label><span>参考素材 ID（每行一个）</span><textarea v-model="rowDraft.referenceArtifactIdsText" rows="3"></textarea></label>
          </details>
          <details open><summary>生成提示词</summary>
            <label><span>首帧提示词</span><textarea v-model="rowDraft.firstFramePrompt" rows="4"></textarea></label><label><span>尾帧提示词</span><textarea v-model="rowDraft.endFramePrompt" rows="4"></textarea></label><label><span>图生视频提示词</span><textarea v-model="rowDraft.videoPrompt" rows="5"></textarea></label>
          </details>
          <details v-if="rowDraft.id" class="evidence-contract"><summary>只读来源证据</summary>
            <dl><div><dt>改编方案</dt><dd>{{rowDraft.adaptationPlanId||'人工分镜'}}</dd></div><div><dt>15 秒方案单元</dt><dd>{{rowDraft.adaptationUnitId||'未绑定'}}</dd></div><div><dt>事实引用</dt><dd>{{selectedRow?.upstreamFactRefs?.map(ref=>`${ref.id}@r${ref.revision}`).join('、')||'无'}}</dd></div><div><dt>节拍引用</dt><dd>{{selectedRow?.upstreamBeatRefs?.map(ref=>`${ref.id}@r${ref.revision}`).join('、')||'无'}}</dd></div></dl>
            <blockquote v-for="span in selectedRow?.sourceSpans||[]" :key="`${span.chapterId}-${span.startOffset}`"><b>{{span.chapterId}} · {{span.startOffset}}–{{span.endOffset}}</b><p>{{span.text}}</p></blockquote>
          </details>
          <button class="primary-button" :disabled="saving" @click="saveRow"><Save :size="14" />保存分镜</button>
        </section>
      </div>
    </template>

    <template v-else-if="tab==='consistency'">
      <div v-if="consistencyState && currentConsistencyBatch" class="consistency-layout" data-testid="fusion-asset-consistency-view">
        <section class="consistency-overview">
          <header><div><span class="eyebrow">每六张暂停复核</span><h3>{{currentConsistencyBatch.id}} · {{consistencyStatusLabel(currentConsistencyBatch.status)}}</h3><p>跨图证据绑定 Publication、raw/labeled、单图 Review、权威参考与 SHA；通过后仍须把六项当前版本逐一提升硬锁。</p></div><div class="consistency-actions"><button data-testid="refresh-fusion-asset-consistency" :disabled="saving" @click="loadConsistency(true)">刷新证据</button><button data-testid="prepare-fusion-asset-consistency" :disabled="saving" @click="prepareConsistencyReview">{{consistencyState.persisted?'准备 2×3 复核板':'接管当前六项'}}</button></div></header>
          <div class="consistency-metrics"><div><span>批次槽位</span><b>{{currentConsistencyBatch.memberCount}} / 6</b></div><div><span>证据就绪</span><b>{{currentConsistencyBatch.readyCount}} / {{currentConsistencyBatch.memberCount}}</b></div><div><span>当前硬锁</span><b>{{currentConsistencyBatch.hardLockCount}} / {{currentConsistencyBatch.memberCount}}</b></div><div><span>复核有效</span><b>{{currentConsistencyBatch.reviewValid?'是':'否'}}</b></div></div>
          <div class="consistency-production-order" data-testid="fusion-asset-production-order"><span>冻结生产顺序 · {{consistencyState.productionOrder.version}} · 已入批 {{consistencyState.productionOrder.reservedAssets}} / {{consistencyState.productionOrder.totalAssets}}</span><b>下一批：{{consistencyState.productionOrder.nextBatchAssetIds.join(' → ')||'全季资产已全部入批'}}</b></div>
          <div class="consistency-members">
            <article v-for="member in currentConsistencyBatch.members" :key="member.itemId" :class="{ready:member.ready,locked:member.hardLocked}" :data-testid="`consistency-member-${member.assetId}`">
              <div><span>{{String(member.order).padStart(2,'0')}}</span><b>{{member.assetId}} · {{member.assetName}}</b><small>{{member.category}} · {{member.jobStatus||'无任务'}}</small></div>
              <em>{{member.ready?'证据齐备':'待证据'}} · {{member.hardLocked?'已硬锁':'未硬锁'}}</em>
              <ul v-if="member.issues.length"><li v-for="issue in member.issues.slice(0,3)" :key="issue">{{issue}}</li></ul>
              <label v-if="consistencyDecision==='rework'"><input v-model="consistencyReworkItems" type="checkbox" :value="member.itemId" />本项返工</label>
            </article>
          </div>
          <div v-if="currentConsistencyBatch.blockingIssues.length" class="consistency-blockers"><b>当前阻塞</b><span v-for="issue in currentConsistencyBatch.blockingIssues.slice(0,8)" :key="issue">{{issue}}</span></div>
          <footer><span>store r{{consistencyState.storeRevision}} · {{consistencyState.persisted?'已持久化':'尚未接管'}}</span><button v-if="consistencyBoard" @click="showConsistencyBoard">定位复核板</button><small v-if="consistencyBoard">{{consistencyBoard.path}}</small></footer>
        </section>
        <section class="consistency-review">
          <span class="eyebrow">跨资产人工复核</span><h3>七项必须逐项选择</h3><p>默认不预填“通过”。包含 P01 时，“黄金面具隐藏铁律”必须明确通过：实体、金边、眼口、裂缝均不可见。</p>
          <label v-for="criterion in consistencyCriteria" :key="criterion.key"><span>{{criterion.label}}</span><select v-model="consistencyCriterionResults[criterion.key]" :data-testid="`consistency-criterion-${criterion.key}`"><option value="">未检查</option><option value="pass">通过</option><option value="fail">失败</option><option value="na">不适用</option></select></label>
          <div class="decision-row"><label><input v-model="consistencyDecision" type="radio" value="pass" />整体通过</label><label><input v-model="consistencyDecision" type="radio" value="rework" />返工</label></div>
          <label><span>复核说明</span><textarea v-model="consistencyNote" rows="5" placeholder="记录脸、犬纹、场景布局、道具结构或面具铁律结论"></textarea></label>
          <button class="primary-button" data-testid="submit-fusion-asset-consistency" :disabled="!canSubmitConsistency||saving" @click="submitConsistencyReview">提交内容绑定复核</button>
          <button v-if="!currentConsistencyBatch.sealed&&currentConsistencyBatch.memberCount>0&&currentConsistencyBatch.memberCount<6" class="ghost-button" :disabled="saving" @click="sealFinalConsistencyBatch">封存全季最终不足六项</button>
        </section>
      </div>
      <div v-else class="empty"><span>{{consistencyUnavailable||'当前没有资产一致性批次'}}</span><button @click="loadConsistency(true)">重新读取</button></div>
    </template>

    <template v-else>
      <div class="registry-layout">
        <section class="registry-panel"><header><div><span class="eyebrow">资产血缘</span><h3>父子衍生与版本关系 · {{relations.length}}</h3></div><button data-testid="new-asset-relation" @click="newRelation"><Plus :size="14" /></button></header>
          <div class="registry-list"><button v-for="relation in relations" :key="relation.id" type="button" data-testid="asset-relation-row" :data-relation-id="relation.id" :class="{active:relationDraft.id===relation.id}" @click="editRelation(relation)"><span>{{relation.kind}}</span><b>{{relation.parentArtifactId||relation.parentItemId}} → {{relation.childArtifactId||relation.childItemId}}</b><small>{{relation.operation||relation.note||'未填写衍生说明'}} · r{{relation.revision}}</small></button><p v-if="!relations.length">尚未登记衍生关系</p></div>
