const props=defineProps<{projectRoot:string;index:ProjectIndex}>(); const emit=defineEmits<{changed:[string];failed:[string]}>();
const tabs=[{id:"workflow",label:"生产状态机",icon:markRaw(Workflow)},{id:"bibles",label:"导演 / 视觉 Bible",icon:markRaw(BookOpenCheck)},{id:"storyboard",label:"正式分镜表",icon:markRaw(Layers3)},{id:"consistency",label:"六张复核",icon:markRaw(ShieldCheck)},{id:"registry",label:"资产 / 音色",icon:markRaw(AudioLines)}] as const;
const tab=ref<(typeof tabs)[number]["id"]>("workflow"),loading=ref(true),saving=ref(false),workflow=ref<ProductionWorkflow|null>(null),bibles=ref<CreativeBible[]>([]),relations=ref<AssetRelation[]>([]),voices=ref<VoiceIdentity[]>([]),selectedStageId=ref<ProductionWorkflowStageId>("source"),impact=ref<unknown>(null);
const units=computed(()=>props.index.items.filter(item=>item.type==="unit").sort((a,b)=>(a.episode??0)-(b.episode??0)||(a.unit??0)-(b.unit??0))); const storyboardItemId=ref("");
const selectedCanvasUnit=computed(()=>props.index.items.find(item=>item.id===storyboardItemId.value));
