const gridContract=ref<FusionStoryboardGridContract|null>(null),sheetResult=ref<FusionStoryboardSheetProductionResult|null>(null),sheetState=ref<FusionStoryboardSheetState|null>(null),sheetStateLoading=ref(false),sheetStateError=ref("");
let storyboardRequestSequence=0;
const expectedSheetFingerprint=computed(()=>sheetState.value?.readiness.expectedInputFingerprint??"");
const migrationPreview=computed(()=>sheetState.value?.migrationPreview);
const sheetHistory=computed(()=>sheetState.value?.versions.filter(version=>version.sheetId!==sheetState.value?.currentSheetId)??[]);
const canRenderSheet=computed(()=>Boolean(!saving.value&&!sheetStateLoading.value&&sheetState.value?.itemId===storyboardItemId.value&&sheetState.value.readiness.canRender&&isSha256(expectedSheetFingerprint.value)&&gridContract.value&&sheetState.value.currentContract?.contractId===gridContract.value.contractId));
const canMigrateSheet=computed(()=>Boolean(!saving.value&&!sheetStateLoading.value&&sheetState.value?.itemId===storyboardItemId.value&&migrationPreview.value?.canMigrate&&migrationPreview.value.candidateCount>0&&Number.isInteger(migrationPreview.value.storeRevision)&&isSha256(migrationPreview.value.candidateFingerprint)));
const unitShots=computed(()=>props.index.items.filter(item=>item.type==="shot"&&item.parentId===storyboardItemId.value).sort((a,b)=>a.title.localeCompare(b.title,"zh-CN")));
const stageDraft=ref<{id:ProductionWorkflowStageId;name:string;status:ProductionWorkflowStageStatus;note:string;evidenceText:string;itemText:string;inputText:string;outputText:string;acceptanceText:string;failureText:string;actionsText:string}|null>(null);
const selectedStageAudit=computed(()=>workflow.value?.evidenceAudit?.stages.find(stage=>stage.stageId===selectedStageId.value));
const stageMetricKeys:Record<ProductionWorkflowStageId,string[]>={source:["sources"],chapters:["sources","chapters"],events:["confirmedEvents"],skeleton:["confirmedEvents"],adaptation:["facts","beats","plans"],episodes:["materializedPlans","activeUnits"],director:["directorBibles"],visual_bible:["visualBibles"],assets:["hardLocks","assetItems"],storyboard:["activeUnits","confirmedStoryboardRows"],frames:["activeUnits","reviewPasses"],video:["activeUnits","reviewPasses"],edit:["editProjects","succeededRenders"],review:["succeededRenders","reviewPasses"],publish:["publicationReceipts"]};
