const relationDraft=reactive({id:"",revision:0,kind:"derived_from" as AssetRelationKind,parentItemId:"",childItemId:"",operation:"",note:""});
const voiceDraft=reactive({id:"",revision:0,name:"",provider:"",providerVoiceId:"",language:"zh-CN",description:"",sampleText:"",characterText:"",hardLockId:""});
const consistencyState=ref<FusionAssetConsistencyState|null>(null),consistencyBoard=ref<FusionAssetConsistencyReviewBoard|null>(null),consistencyUnavailable=ref("");
const consistencyDecision=ref<"pass"|"rework">("pass"),consistencyNote=ref(""),consistencyReworkItems=ref<string[]>([]);
const consistencyCriteria:Array<{key:FusionAssetConsistencyCriterionKey;label:string}>=[{key:"character_identity",label:"角色身份 / 发型 / 服装跨图一致"},{key:"era_visual_style",label:"商周时代与电影写实风格统一"},{key:"scene_layout_lighting",label:"场景布局、材质、色温和光源逻辑兼容"},{key:"scale_compatibility",label:"人物、道具、场景比例可共存"},{key:"prop_structure",label:"道具轮廓与结构稳定"},{key:"clean_frame",label:"无现代物、字幕、水印、拼图或多余人物"},{key:"hidden_mask_rule",label:"黄金面具隐藏铁律（P01 批次强制）"}];
const consistencyCriterionResults=reactive<Record<FusionAssetConsistencyCriterionKey,""|FusionAssetConsistencyCriterionResult>>({character_identity:"",era_visual_style:"",scene_layout_lighting:"",scale_compatibility:"",prop_structure:"",clean_frame:"",hidden_mask_rule:""});
const currentConsistencyBatch=computed(()=>consistencyState.value?.batches.at(-1));
const canSubmitConsistency=computed(()=>{const batch=currentConsistencyBatch.value;if(!batch?.canPrepareReview||!batch.currentSnapshotHash||!consistencyNote.value.trim()||!consistencyCriteria.every(entry=>consistencyCriterionResults[entry.key]))return false;if(consistencyDecision.value==="rework")return consistencyReworkItems.value.length>0&&consistencyCriteria.some(entry=>consistencyCriterionResults[entry.key]==="fail");return consistencyCriteria.every(entry=>consistencyCriterionResults[entry.key]==="pass"||(entry.key==="hidden_mask_rule"&&!batch.includesHiddenMaskAsset&&consistencyCriterionResults[entry.key]==="na"))});
onMounted(load);
// FE-07：切工程显式重载（不再依赖 App 卸载重建的隐式契约）。
watch(() => props.projectRoot, () => void load());
async function load(){loading.value=true;try{[workflow.value,bibles.value,relations.value,voices.value]=await Promise.all([window.canvasApi.getProductionWorkflow(props.projectRoot),window.canvasApi.listCreativeBibles(props.projectRoot),window.canvasApi.listAssetRelations(props.projectRoot),window.canvasApi.listVoiceIdentities(props.projectRoot)]);selectStage("source");storyboardItemId.value=units.value[0]?.id??"";await Promise.all([loadStoryboard(),loadConsistency(false)])}catch(e){emit("failed",msg(e))}finally{loading.value=false}}
async function loadConsistency(report=true){try{consistencyState.value=await window.canvasApi.getFusionAssetConsistency(props.projectRoot);consistencyUnavailable.value=""}catch(e){consistencyState.value=null;consistencyUnavailable.value=msg(e);if(report)emit("failed",msg(e))}}
async function showConsistencyBoard(){if(!consistencyBoard.value)return;await window.canvasApi.showInFolder(consistencyBoard.value.path)}
async function prepareConsistencyReview(){saving.value=true;try{const result=await window.canvasApi.prepareFusionAssetConsistencyReview(props.projectRoot,{batchId:currentConsistencyBatch.value?.id});consistencyState.value=result.state;consistencyBoard.value=result.board??null;emit("changed",result.prepared?"六张一致性复核板已按当前内容生成":"已接管批次；仍需完成六项图片、Publication 与单图 Review") }catch(e){emit("failed",msg(e))}finally{saving.value=false}}
async function submitConsistencyReview(){const batch=currentConsistencyBatch.value;if(!batch?.currentSnapshotHash||!consistencyState.value)return;saving.value=true;try{consistencyState.value=await window.canvasApi.submitFusionAssetConsistencyReview(props.projectRoot,{batchId:batch.id,expectedRevision:consistencyState.value.storeRevision,expectedSnapshotHash:batch.currentSnapshotHash,decision:consistencyDecision.value,criteria:consistencyCriteria.map(entry=>({key:entry.key,result:consistencyCriterionResults[entry.key] as FusionAssetConsistencyCriterionResult})),reworkItemIds:consistencyDecision.value==="rework"?consistencyReworkItems.value:undefined,note:consistencyNote.value});emit("changed",consistencyDecision.value==="pass"?"六张跨资产一致性已通过；请逐项提升当前硬锁":"六张跨资产一致性已登记返工");resetConsistencyForm()}catch(e){emit("failed",msg(e))}finally{saving.value=false}}
async function sealFinalConsistencyBatch(){const batch=currentConsistencyBatch.value;if(!batch||!consistencyState.value)return;saving.value=true;try{consistencyState.value=await window.canvasApi.sealFinalFusionAssetConsistencyBatch(props.projectRoot,{batchId:batch.id,expectedRevision:consistencyState.value.storeRevision});emit("changed","全季最终不足六项批次已显式封存") }catch(e){emit("failed",msg(e))}finally{saving.value=false}}
function resetConsistencyForm(){for(const entry of consistencyCriteria)consistencyCriterionResults[entry.key]="";consistencyDecision.value="pass";consistencyNote.value="";consistencyReworkItems.value=[]}
function consistencyStatusLabel(status:string){return({collecting:"收集中",generating:"生成中",awaiting_item_reviews:"等待单图验收",awaiting_batch_review:"等待六张复核",passed:"复核通过",rework:"返工",invalidated:"证据失效"} as Record<string,string>)[status]??status}
async function reloadWorkflow(){saving.value=true;try{const selected=selectedStageId.value;workflow.value=await window.canvasApi.getProductionWorkflow(props.projectRoot);selectStage(selected)}catch(e){emit("failed",msg(e))}finally{saving.value=false}}
function stageAudit(id:ProductionWorkflowStageId){return workflow.value?.evidenceAudit?.stages.find(stage=>stage.stageId===id)}
function selectStage(id:ProductionWorkflowStageId){selectedStageId.value=id;const stage=workflow.value?.stages.find(s=>s.id===id);if(stage)stageDraft.value={id:stage.id,name:stage.name,status:stage.status,note:stage.note??"",evidenceText:stage.evidencePaths.join("\n"),itemText:stage.itemIds.join("\n"),inputText:stage.inputRequirements.join("\n"),outputText:stage.outputRequirements.join("\n"),acceptanceText:stage.acceptanceCriteria.join("\n"),failureText:stage.failurePaths.join("\n"),actionsText:stage.nextActions.join("\n")}}
async function saveStage(){if(!workflow.value||!stageDraft.value)return;saving.value=true;try{const selected=stageDraft.value.id;await window.canvasApi.updateProductionWorkflowStage(props.projectRoot,{stageId:selected,status:stageDraft.value.status,note:stageDraft.value.note,evidencePaths:lines(stageDraft.value.evidenceText),itemIds:lines(stageDraft.value.itemText),inputRequirements:lines(stageDraft.value.inputText),outputRequirements:lines(stageDraft.value.outputText),acceptanceCriteria:lines(stageDraft.value.acceptanceText),failurePaths:lines(stageDraft.value.failureText),nextActions:lines(stageDraft.value.actionsText),expectedRevision:workflow.value.revision});workflow.value=await window.canvasApi.getProductionWorkflow(props.projectRoot);selectStage(selected);emit("changed","生产阶段已保存并重新核验证据") }catch(e){emit("failed",msg(e))}finally{saving.value=false}}
function newBible(){Object.assign(bibleDraft,{id:"",kind:"director",name:"",summary:"",rulesText:"",forbiddenText:"",referencesText:"",revision:0});impact.value=null}
