async function saveBible(){saving.value=true;try{const fields={kind:bibleDraft.kind,name:bibleDraft.name,summary:bibleDraft.summary,rules:lines(bibleDraft.rulesText),forbidden:lines(bibleDraft.forbiddenText),referencePaths:lines(bibleDraft.referencesText)};const saved=bibleDraft.id?await window.canvasApi.upsertCreativeBible(props.projectRoot,{...fields,id:bibleDraft.id,expectedRevision:bibleDraft.revision}):await window.canvasApi.upsertCreativeBible(props.projectRoot,fields);bibles.value=await window.canvasApi.listCreativeBibles(props.projectRoot);editBible(saved);emit("changed","创作 Bible 已保存") }catch(e){emit("failed",msg(e))}finally{saving.value=false}}
async function impactBible(){if(!bibleDraft.id)return;try{impact.value=await window.canvasApi.analyzeChangeImpact(props.projectRoot,{targetType:"bible",targetId:bibleDraft.id})}catch(e){emit("failed",msg(e))}}
function applySheetState(state:FusionStoryboardSheetState){sheetState.value=state;gridContract.value=state.currentContract??null;sheetStateError.value=""}
async function loadStoryboard(){
  const itemId=storyboardItemId.value;const requestSequence=++storyboardRequestSequence;
  gridContract.value=null;sheetResult.value=null;sheetState.value=null;sheetStateError.value="";sheetStateLoading.value=Boolean(itemId);
  Object.assign(storyboard,{revision:0,rows:[],totalDurationSeconds:0,valid:true,issues:[]});newRow();
  if(!itemId)return;
  try{
    const [storyboardResult,stateResult]=await Promise.allSettled([window.canvasApi.getStoryboard(props.projectRoot,itemId),window.canvasApi.getFusionStoryboardSheetState(props.projectRoot,{itemId})]);
    if(requestSequence!==storyboardRequestSequence||itemId!==storyboardItemId.value)return;
    if(storyboardResult.status==="fulfilled"){Object.assign(storyboard,storyboardResult.value);if(storyboard.rows[0])editRow(storyboard.rows[0]);else newRow()}else emit("failed",msg(storyboardResult.reason));
    if(stateResult.status==="fulfilled")applySheetState(stateResult.value);else{sheetState.value=null;gridContract.value=null;sheetStateError.value=msg(stateResult.reason);emit("failed",sheetStateError.value)}
