async function refreshSheetState(report=true){
  const itemId=storyboardItemId.value;const requestSequence=++storyboardRequestSequence;
  if(!itemId){sheetState.value=null;gridContract.value=null;sheetStateError.value="";sheetStateLoading.value=false;return false}
  sheetStateLoading.value=true;
  try{const state=await window.canvasApi.getFusionStoryboardSheetState(props.projectRoot,{itemId});if(requestSequence!==storyboardRequestSequence||itemId!==storyboardItemId.value)return false;applySheetState(state);return true}
  catch(e){if(requestSequence!==storyboardRequestSequence)return false;sheetState.value=null;gridContract.value=null;sheetStateError.value=msg(e);if(report)emit("failed",sheetStateError.value);return false}
  finally{if(requestSequence===storyboardRequestSequence)sheetStateLoading.value=false}
}
async function buildStoryboardGrid(){if(!storyboardItemId.value)return;saving.value=true;try{const contract=await window.canvasApi.buildFusionStoryboardGrid(props.projectRoot,{itemId:storyboardItemId.value});sheetResult.value=null;if(!await refreshSheetState(false))throw new Error("宫格合同已构建，但权威成板状态重读失败。");emit("changed",`已按剧情建立 ${contract.selection.panelCount} 格合同 · ${contract.contractId}`)}catch(e){const error=msg(e);await refreshSheetState(false);emit("failed",error)}finally{saving.value=false}}
async function migrateStoryboardEvidence(){if(!storyboardItemId.value)return;saving.value=true;try{const result=await window.canvasApi.migrateFusionStoryboardEvidence(props.projectRoot,{itemIds:[storyboardItemId.value]});const item=result.items[0];if(!await refreshSheetState(false))throw new Error("槽位证据已迁移，但权威成板状态重读失败。");emit("changed",item?`宫格槽位证据：${item.completedPanelCount??0}/${item.panelCount??0} 格 · Review ${item.review}`:"当前单元没有可迁移宫格证据")}catch(e){const error=msg(e);await refreshSheetState(false);emit("failed",error)}finally{saving.value=false}}
async function migrateStoryboardSheets(){const itemId=storyboardItemId.value,preview=migrationPreview.value;if(!itemId||!canMigrateSheet.value||!preview)return;saving.value=true;try{const result=await window.canvasApi.migrateFusionStoryboardSheets(props.projectRoot,{itemIds:[itemId],expectedStoreRevision:preview.storeRevision,expectedCandidateFingerprint:preview.candidateFingerprint});if(!await refreshSheetState(false))throw new Error("旧板已登记，但权威成板状态重读失败。");emit("changed",`已将 ${result.created} 个旧板登记为历史版本 · store r${result.storeRevision}`)}catch(e){const error=msg(e);await refreshSheetState(false);emit("failed",error)}finally{saving.value=false}}
async function enqueueStoryboardPanel(panelIndex:number){if(!storyboardItemId.value||!gridContract.value||!canEnqueueStoryboardPanel(panelIndex))return;saving.value=true;try{const jobs=await window.canvasApi.enqueueGeneration(props.projectRoot,{itemIds:[storyboardItemId.value],kind:"image",fusionStoryboardPanel:{contractId:gridContract.value.contractId,panelIndex}});await refreshSheetState(false);emit("changed",`第 ${panelIndex} 格已加入逐格队列 · ${jobs[0]?.id??''}`)}catch(e){const error=msg(e);await refreshSheetState(false);emit("failed",error)}finally{saving.value=false}}
async function renderStoryboardSheet(){const itemId=storyboardItemId.value,contract=gridContract.value,inputFingerprint=expectedSheetFingerprint.value;if(!itemId||!contract||!canRenderSheet.value)return;saving.value=true;try{sheetResult.value=await window.canvasApi.renderFusionStoryboardSheet(props.projectRoot,{itemId,contractId:contract.contractId,expectedInputFingerprint:inputFingerprint});if(!await refreshSheetState(false))throw new Error("成板已生成，但权威成板状态重读失败。");emit("changed",`中文分镜故事板已生成：${sheetResult.value.png.path}`)}catch(e){const error=msg(e);await refreshSheetState(false);emit("failed",error)}finally{saving.value=false}}
async function showStoryboardSheet(){if(sheetResult.value)await window.canvasApi.showInFolder(sheetResult.value.png.path)}
async function showSheetArtifact(filePath:string){await window.canvasApi.showInFolder(filePath)}
function panelState(panelIndex:number){const progress=selectedCanvasUnit.value?.fusionStoryboard;if(!progress||progress.contractId!==gridContract.value?.contractId)return"未扫描";const panel=progress.panels.find(entry=>entry.panelIndex===panelIndex);return panel?.state??"未扫描"}
function canEnqueueStoryboardPanel(panelIndex:number){if(saving.value)return false;const state=panelState(panelIndex);return state==="missing"||state==="visual_rejected"}
function emptyRow(){return{id:"",revision:0,shotItemId:"",order:storyboard.rows.length+1,durationSeconds:Math.min(3,Math.max(.5,15-storyboard.totalDurationSeconds)),shotSize:"中景",cameraMovement:"固定",cameraAngle:"",lens:"",composition:"",staging:"",action:"",expression:"",emotion:"",eyeline:"",screenDirection:"",axisSide:"",dialogue:"",narration:"",ambience:"",soundEffectsText:"",continuityBefore:"",continuityAfter:"",referenceNamesText:"",firstFramePrompt:"",endFramePrompt:"",videoPrompt:"",referencePathsText:"",referenceArtifactIdsText:"",adaptationPlanId:"",adaptationUnitId:"",directorIntent:"",emotionalIntent:"",continuityNotesText:"",status:"draft" as StoryboardRow["status"]}}
